/** Schema of data/words.json. */

export interface ExampleSentence {
  /** The sentence in simplified characters. */
  zh: string;
  /** Pinyin generated from the sentence with pinyin-pro + dictionary readings. */
  pinyin: string;
  /** English translation. */
  en: string;
  /** "manual" = hand-written and checked; "llm" = generated by the build script. */
  source: "manual" | "llm";
  /** Bank words in the sentence ranked after the target word. */
  later: string[];
  /** Words in the sentence that can't be built from bank words at all. */
  outside: string[];
  /** True when the sentence still breaks the rules after all retries. */
  flagged: boolean;
}

export interface OtherReading {
  pinyin: string;
  pinyinNum: string;
  meaning: string;
}

export interface BankWord {
  /** Stable id (frequency rank on the first build; never reused). */
  id: number;
  simplified: string;
  /** Stored for later use (traditional-character mode). */
  traditional: string;
  /** Tone marks, syllables joined: "jīntiān", "yīdiǎnr". Citation form (no tone sandhi). */
  pinyin: string;
  /** Tone numbers, space separated: "jin1 tian1", "yi1 dian3 r5". */
  pinyinNum: string;
  /** Short English gloss shown on cards, e.g. "today". */
  meaning: string;
  /** Fuller dictionary definitions (from the HSK dataset / CC-CEDICT). */
  meanings: string[];
  /** Where `meaning` came from. */
  glossSource: "auto" | "manual" | "llm";
  /** Part-of-speech codes from the HSK dataset (v, n, a, d, r, ...). */
  pos: string[];
  /** HSK 3.0 level (1–3). */
  hsk: number;
  /** Frequency rank inside the bank: 1 = most common. Learning order. */
  rank: number;
  /** Frequency rank from the HSK dataset's corpus (null if it had none). */
  corpusRank: number | null;
  /** Occurrences per billion words of text (wordfreq); 0 if unknown. */
  freq: number;
  otherReadings: OtherReading[];
  example: ExampleSentence | null;
}

export interface WordBankFile {
  version: 1;
  generatedAt: string;
  count: number;
  sources: Record<string, string>;
  words: BankWord[];
}
